import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/inscription.md","filePath":"es/game-design/professions/inscription.md"}'),o={name:"es/game-design/professions/inscription.md"};function r(c,e,t,d,l,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Enlace permanente a &quot;Inscription&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las decisiones enumeradas siguen Sin resolver. Los fundamentos existentes en estado Aceptado conservan su alcance. <strong>Implementación:</strong> no se ha establecido ninguna implementación de gameplay del Batch 04. <strong>Disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo conciliación documental, no validación en ejecución. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04 y al <a href="/Syrolands-Public/es/game-design/magic.html">diseño mágico anterior</a>.</p><p><a href="/Syrolands-Public/es/guide/professions/inscription.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Panorama de magia</a> · <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado y preguntas abiertas</a></p><h2 id="inscription-as-magical-engineering" tabindex="-1">Inscription como ingeniería mágica <a class="header-anchor" href="#inscription-as-magical-engineering" aria-label="Enlace permanente a &quot;Inscription como ingeniería mágica&quot;">​</a></h2><p>Un escriba maestro registra, modifica, conserva, prepara e incorpora estructuras mágicas en vez de limitarse a imprimir pergaminos. Los ámbitos candidatos son:</p><ul><li>Fabricación de pergaminos, que potencialmente requiere conocimiento personal de hechizos avanzados.</li><li>Ampliaciones de hechizos, glifos y fórmulas.</li><li>Runas o glifos en objetos, puertas, casas, terreno y rituales.</li><li>Salvaguardas y protecciones preparadas.</li><li>Estructuras especializadas de libros de hechizos/grimorios.</li><li>Componentes rituales codificados.</li><li>Conservación y copia solo donde el diseño lo permita explícitamente.</li></ul><p>Copiar no debe recrear silenciosamente un mercado comerciable de aprendizaje permanente. Las reglas exactas de producción y recetas no están terminadas.</p><p>El Batch 04 amplía la estructura mágica escrita hacia transformación y transmisión controladas: pergaminos de variantes, construcción de glifos, diseño de modificadores estables, escritura/encuadernación de grimorios, optimización de indexación/consulta, protecciones, diagramas rituales, notación y conservación de escuelas/técnicas raras. Son actividades candidatas, no un menú final de fabricación ni un sistema funcional de protecciones.</p><h2 id="skill-technique-and-profession-path" tabindex="-1">Habilidad, técnica y vía profesional <a class="header-anchor" href="#skill-technique-and-profession-path" aria-label="Enlace permanente a &quot;Habilidad, técnica y vía profesional&quot;">​</a></h2><p>Usar el modelo compartido <strong>Habilidad → Técnica/Escuela → Vía profesional</strong>. Inscription proporciona capacidad de ejecución; los métodos aprendidos y el acceso al conocimiento determinan qué se puede codificar. Magery no otorga automáticamente cada patrón, e Inscription por sí sola no implica poseer conocimiento raro.</p><p>Basic Spell Scribing, Glyph Construction, Advanced Indexing, Ward Inscription, Ritual Diagramming, Variant Stabilization y Grimoire Binding son técnicas ilustrativas. Un escriba podría especializarse en pergaminos de combate, conservación de variantes raras, protecciones, notación ritual o grimorios de alta calidad. No se elige árbol final gigante, habilidades elementales adicionales ni umbrales automáticos de desbloqueo.</p><h2 id="knowledge-production-and-economy" tabindex="-1">Conocimiento, producción y economía <a class="header-anchor" href="#knowledge-production-and-economy" aria-label="Enlace permanente a &quot;Conocimiento, producción y economía&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define diarios/Codex, secretos, enseñanza parcial, descubrimiento manual, producción por lotes, encargos y reputación. Aplicar esas preguntas compartidas a la notación mágica sin inventar un minijuego de producción separado, desbloqueo permanente de recetas ni servicio económico nuevo.</p><p>Magery, patrones conocidos, técnicas/escuelas, reactivos y Alchemy pueden interactuar con Inscription. Las dependencias rituales/religiosas son posibles más adelante, no sistemas requeridos ahora. La investigación y conservación deberían dar a los escribas funciones económicas más allá de vender bonificaciones de habilidad: acceso mediante pergaminos de emergencia, variantes fiables, buena indexación y notación rara. La reputación puede reflejar productos útiles y procedencia bajo la dirección compartida de profesiones, no una fórmula definitiva de calificación.</p><p>Las <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html">ventajas de consulta de pergaminos y el riesgo material</a> preservan costes consumibles y exposición al saqueo. Copia/transmisión deben respetar el límite sin resolver de artefactos de enseñanza; enseñar entre jugadores no es duplicación permanente irrestricta de hechizos. Técnicas raras y secretos necesitan reglas de custodia y descubrimiento resistentes al abuso antes de implementarse.</p><h2 id="workmanship-and-reference-quality" tabindex="-1">Elaboración y calidad de consulta <a class="header-anchor" href="#workmanship-and-reference-quality" aria-label="Enlace permanente a &quot;Elaboración y calidad de consulta&quot;">​</a></h2><p>La organización de grimorios, notación estable, variantes indexadas y notas del propietario pueden mejorar consulta/preparación. Evitar el diseño fijo de “libro otorga +10 Magery”. Los libros fabricados y los obtenidos como botín deberían encajar en <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">calidad compartida e itemización horizontal</a>; ni artesanía ni terminología Sacred/Resonant otorgan protección al morir.</p><h2 id="authority-and-technical-limits" tabindex="-1">Autoridad y límites técnicos <a class="header-anchor" href="#authority-and-technical-limits" aria-label="Enlace permanente a &quot;Autoridad y límites técnicos&quot;">​</a></h2><p>El servidor valida conocimiento, prerrequisitos, materiales, propiedad, trabajo, consumo y resultados. El cliente presenta escritura, navegación del libro e información; las animaciones no completan una fabricación ni autorizan un lanzamiento. No se eligen cambios de motor, tablas de recetas, clases de objetos, esquemas de persistencia ni paquetes.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Catálogo final de técnicas; prerrequisitos de fabricación y variantes; permisos de copia/enseñanza; secreto/procedencia de notación; producción y reglas de interrupción/materiales; alcance de protecciones/rituales; ventajas de encuadernación/indexación; abuso de calidad y reputación; relación con futuros sistemas rituales/religiosos. Toda implementación y balance requieren alcance separado.</p><h2 id="proposed-training-facilities-—-batch-05" tabindex="-1">Instalaciones de entrenamiento en estado Propuesto — Batch 05 <a class="header-anchor" href="#proposed-training-facilities-—-batch-05" aria-label="Enlace permanente a &quot;Instalaciones de entrenamiento en estado Propuesto — Batch 05&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/familiarity.html#training-facilities-and-crafts">Familiarity e instalaciones compartidas</a> considera muñecos fabricados, blancos articulados/móviles, mecanismos de campo de tiro y focos de práctica mágica, con Carpentry, Tinkering e Inscription como posibles participantes. Aquí no se asignan funciones/recetas. Las instalaciones deberían mantener eficientemente la fluidez, no convertirse en el método óptimo de repetición para subir habilidades básicas ni eludir el descubrimiento.</p>',23)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
